// Thresholds set against the REAL rating distribution (floor 72,
// median 79, ceiling 92). Verified spread across 651 players:
//   elite    87+  ~4%   -- genuinely rare
//   platinum 83+  ~15%
//   forest   79+  ~31%
//   midnight 75+  ~31%
//   sand     rest ~19%
// Deliberately top-heavy rather than an even quota: these are Premier
// League footballers, so only a minority should sit in the bottom tier.
//
// Special editions are checked FIRST and override the rating tier
// entirely. Both need a real rating as well as the age condition --
// without that, every teenage academy squad-filler would get a
// wonderkid card and the whole thing would stop meaning anything.
function tierFor(rating, age) {
  const r = rating || 0;

  // Under 21 and already performing at a decent level.
  if (age && age <= 21 && r >= 79) return TIERS.wonderkid;
  // Still going strong at an age where most have declined.
  if (age && age >= 32 && r >= 81) return TIERS.veteran;

  if (r >= 87) return TIERS.elite;
  if (r >= 83) return TIERS.platinum;
  if (r >= 79) return TIERS.forest;
  if (r >= 75) return TIERS.midnight;
  return TIERS.sand;
}

