// Real flags, rendered natively by the OS. A two-letter country code
// maps directly onto regional indicator symbols, so every ISO country
// works automatically and accurately -- no hand-drawn approximations,
// and no 91 base64 images to ship. England and Wales aren't ISO
// countries (they're UK subdivisions), so they use the separate emoji
// tag-sequence form instead.
const FLAG_TAG_SEQUENCES = {
  EN: '\u{1F3F4}\u{E0067}\u{E0062}\u{E0065}\u{E006E}\u{E0067}\u{E007F}', // England
  WA: '\u{1F3F4}\u{E0067}\u{E0062}\u{E0077}\u{E006C}\u{E0073}\u{E007F}', // Wales
  SCT: '\u{1F3F4}\u{E0067}\u{E0062}\u{E0073}\u{E0063}\u{E0074}\u{E007F}', // Scotland
};

function flagEmoji(code) {
  if (!code) return '';
  const cc = String(code).toUpperCase();
  if (FLAG_TAG_SEQUENCES[cc]) return FLAG_TAG_SEQUENCES[cc];
  if (cc.length !== 2) return '';
  return cc.replace(/./g, (c) => String.fromCodePoint(127397 + c.charCodeAt(0)));
}


